+using System.Web.Script.Serialization;
+using InformationWebObject;
+using DCore;
+namespace InformationWeb.Api
+{
+    public static class PublicApiHelper
+    {
+        public static void WriteJson(HttpContext context, object data)
+        {
+            JavaScriptSerializer serializer = new JavaScriptSerializer();
+            context.Response.ContentType = "application/json";
+            context.Response.ContentEncoding = System.Text.Encoding.UTF8;
+            context.Response.Write(serializer.Serialize(data));
+        }
+        public static void WriteError(HttpContext context, string message)
+        {
+            context.Response.StatusCode = 500;
+            WriteJson(context, CreateError(message));
+        }
+        public static Dictionary<string, object> CreateSuccess(object data)
+        {
+            Dictionary<string, object> result = new Dictionary<string, object>();
+            result["success"] = true;
+            result["data"] = data;
+            return result;
+        }
+        public static Dictionary<string, object> CreateError(string message)
+        {
+            Dictionary<string, object> result = new Dictionary<string, object>();
+            result["success"] = false;
+            result["message"] = message;
+            return result;
+        }
+        public static List<Dictionary<string, object>> ToList(DataTable table)
+        {
+            List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
+            if (table == null)
+            {
+                return list;
+            }
+            foreach (DataRow row in table.Rows)
+            {
+                Dictionary<string, object> item = new Dictionary<string, object>();
+                foreach (DataColumn column in table.Columns)
+                {
+                    object value = row[column];
+                    item[column.ColumnName] = value == DBNull.Value ? null : value;
+                }
+                list.Add(item);
+            }
+            return list;
+        }
+        public static Dictionary<string, object> FirstRow(DataTable table)
+        {
+            List<Dictionary<string, object>> list = ToList(table);
+            if (list.Count == 0)
+            {
+                return null;
+            }
+            return list[0];
+        }
+        public static int GetInt(HttpRequest request, string name, int defaultValue, int minValue, int maxValue)
+        {
+            int value = defaultValue;
+            if (!string.IsNullOrEmpty(request[name]))
+            {
+                int.TryParse(request[name], out value);
+            }
+            if (value < minValue)
+            {
+                return minValue;
+            }
+            if (value > maxValue)
+            {
+                return maxValue;
+            }
+            return value;
+        }
+        public static string GetText(HttpRequest request, string name, int maxLength)
+        {
+            string value = request[name] == null ? string.Empty : request[name].Trim();
+            if (value.Length > maxLength)
+            {
+                value = value.Substring(0, maxLength);
+            }
+            return value;
+        }
